package org.rabochaya.projects;
import android.app.*;import android.content.*;import android.os.*;import android.view.*;import android.widget.*;import java.io.*;import java.util.*;
/** User-managed project composition. Every accepted control action persists its own stack only. */
public final class MapLayersActivity extends Activity {
 private static final int PICK_SOURCE=4521;private long project;private LinearLayout root,list;private ScrollView scroll;private TextView status;private MapCompositionSettings.Snapshot snapshot;private String pendingLayer;private int pendingOpacity,restoreY;private boolean disposed;
 protected void onCreate(Bundle saved){super.onCreate(saved);project=getIntent().getLongExtra("project",-1);getWindow().setStatusBarColor(0xff1c2518);getWindow().setNavigationBarColor(0xff1c2518);restoreY=saved==null?0:saved.getInt("scroll",0);setResult(RESULT_OK);if(project<=0){finish();return;}reload("");}
 private int dp(int value){return WorkspaceUi.dp(this,value);}
 private TextView text(String value,int size){TextView t=new TextView(this);t.setText(value);t.setTextSize(size);t.setTextColor(-1);t.setTypeface(WorkspaceUi.font(this));t.setPadding(dp(8),dp(6),dp(8),dp(6));return t;}
 private Button button(LinearLayout parent,String title,Runnable action){Button b=new Button(this);b.setText(title);b.setAllCaps(false);b.setTextSize(14);b.setTypeface(WorkspaceUi.font(this));b.setMinHeight(dp(48));parent.addView(b,new LinearLayout.LayoutParams(-1,-2));b.setOnClickListener(v->action.run());return b;}
 private void font(View v){if(v instanceof TextView)((TextView)v).setTypeface(WorkspaceUi.font(this));if(v instanceof ViewGroup)for(int i=0;i<((ViewGroup)v).getChildCount();i++)font(((ViewGroup)v).getChildAt(i));}
 private void checkTint(CheckBox box){box.setButtonTintList(new android.content.res.ColorStateList(new int[][]{new int[]{android.R.attr.state_checked},new int[]{}},new int[]{0xff009688,0xffd0d6c9}));}
 private void reload(String message){try{snapshot=MapCompositionSettings.load(this,project);show(message);}catch(Exception e){snapshot=null;show("Не удалось прочитать состав: "+e.getMessage()+". Сохранённые настройки не изменены.");}}
 private void show(String message){if(disposed)return;int y=scroll==null?restoreY:scroll.getScrollY();root=new LinearLayout(this);root.setOrientation(1);root.setPadding(dp(8),dp(4),dp(8),dp(4));root.setBackgroundColor(0xff232d1d);setContentView(root);root.addView(text("Слои карты",22));status=text(message,14);status.setMaxLines(3);root.addView(status);if(snapshot==null){button(root,"К карте",()->finish());return;}
  scroll=new ScrollView(this);LinearLayout content=new LinearLayout(this);content.setOrientation(1);scroll.addView(content);root.addView(scroll,new LinearLayout.LayoutParams(-1,0,1));CheckBox enabled=new CheckBox(this);enabled.setText("Использовать композицию слоёв");enabled.setTextColor(-1);enabled.setTypeface(WorkspaceUi.font(this));checkTint(enabled);enabled.setChecked(snapshot.enabled);content.addView(enabled);enabled.setOnCheckedChangeListener((view,on)->apply(snapshot.composition,on));
  content.addView(text("До "+MapComposition.MAX_LAYERS+" слоёв. Верхний слой показан первым. Удаление слоя сохраняет карты, кеш и объекты. "+(OnlineMapSettings.network(this)?"Онлайн и кеш.":"Только кеш; интернет включается в меню карты."),12));Button add=button(content,"Добавить слой",()->addChoices());add.setEnabled(snapshot.composition.layers.size()<MapComposition.MAX_LAYERS);
  list=new LinearLayout(this);list.setOrientation(1);content.addView(list);if(snapshot.composition.layers.isEmpty())list.addView(text("Подложек нет. Объекты остаются на карте.",16));for(int i=snapshot.composition.layers.size()-1;i>=0;i--)row(snapshot.composition.layers.get(i),i);button(root,"К карте",()->{flushOpacity();finish();});scroll.post(()->{if(!disposed)scroll.scrollTo(0,y);});
 }
 private void addChoices(){flushOpacity();ArrayList<String> names=new ArrayList<>();ArrayList<Runnable> actions=new ArrayList<>();names.add("Из каталога");actions.add(()->startActivityForResult(new Intent(this,MapCatalogActivity.class).putExtra("project",project).putExtra("layer_pick",true),PICK_SOURCE));if(OnlineMapSettings.prefs(this).getString("catalog","").isEmpty()&&OnlineMapSettings.prefs(this).contains("template")){names.add("Настроенный XYZ-источник");actions.add(()->add(MapComposition.Layer.custom(OnlineMapSettings.source(this))));}if(new File(getFilesDir(),"local_basemap_"+project+".mbtiles").isFile()){names.add("MBTiles проекта");actions.add(()->add(MapComposition.Layer.local()));}names.add("Обзорная карта");actions.add(()->add(MapComposition.Layer.bundled()));ArrayAdapter<String> adapter=new ArrayAdapter<String>(this,android.R.layout.select_dialog_item,names){public View getView(int position,View convert,ViewGroup parent){View v=super.getView(position,convert,parent);font(v);return v;}};AlertDialog dialog=new AlertDialog.Builder(this).setTitle("Добавить слой").setAdapter(adapter,(d,w)->actions.get(w).run()).setNegativeButton("Отмена",null).create();dialog.setOnShowListener(v->font(dialog.getWindow().getDecorView()));dialog.show();}
 private void row(final MapComposition.Layer layer,final int index){LinearLayout card=new LinearLayout(this);card.setOrientation(1);card.setPadding(dp(6),dp(6),dp(6),dp(8));card.setBackground(WorkspaceUi.panel());card.setTag(layer.id);LinearLayout.LayoutParams outer=new LinearLayout.LayoutParams(-1,-2);outer.setMargins(0,dp(4),0,dp(4));list.addView(card,outer);card.addView(text(layer.name,18));String detail="local".equals(layer.kind)?"MBTiles проекта":"bundled".equals(layer.kind)?"Обзорная карта":layer.source()==null?"Источник каталога недоступен":layer.source().attribution;card.addView(text(detail,12));CheckBox visible=new CheckBox(this);visible.setText("Показывать слой");visible.setTextColor(-1);visible.setTypeface(WorkspaceUi.font(this));checkTint(visible);visible.setChecked(layer.visible);card.addView(visible);visible.setOnCheckedChangeListener((view,on)->apply(snapshot.composition.visible(layer.id,on),true));TextView amount=text("Непрозрачность: "+layer.opacity+"%",14);card.addView(amount);SeekBar opacity=new SeekBar(this);opacity.setContentDescription("Непрозрачность: "+layer.name);opacity.setMax(100);opacity.setProgress(layer.opacity);card.addView(opacity,new LinearLayout.LayoutParams(-1,dp(48)));opacity.setOnSeekBarChangeListener(new SeekBar.OnSeekBarChangeListener(){public void onStartTrackingTouch(SeekBar bar){}public void onProgressChanged(SeekBar bar,int value,boolean user){amount.setText("Непрозрачность: "+value+"%");if(user){pendingLayer=layer.id;pendingOpacity=value;}}public void onStopTrackingTouch(SeekBar bar){flushOpacity();}});
  LinearLayout actions=new LinearLayout(this);card.addView(actions);Button up=button(actions,"Выше",()->apply(snapshot.composition.move(layer.id,index+1),true)),down=button(actions,"Ниже",()->apply(snapshot.composition.move(layer.id,index-1),true));up.setEnabled(index<snapshot.composition.layers.size()-1);down.setEnabled(index>0);button(actions,"Убрать",()->remove(layer));for(int i=0;i<actions.getChildCount();i++)actions.getChildAt(i).setLayoutParams(new LinearLayout.LayoutParams(0,dp(48),1));
 }
 private void remove(MapComposition.Layer layer){AlertDialog dialog=new AlertDialog.Builder(this).setTitle("Убрать слой?").setMessage(layer.name+"\nИсходная карта, кеш и объекты останутся на устройстве.").setPositiveButton("Убрать",(d,w)->apply(snapshot.composition.remove(layer.id),true)).setNegativeButton("Отмена",null).create();dialog.setOnShowListener(v->font(dialog.getWindow().getDecorView()));dialog.show();}
 private void add(MapComposition.Layer layer){try{apply(snapshot.composition.add(layer),true);}catch(Exception e){status.setText("Слой не добавлен: "+e.getMessage());}}
 private void apply(MapComposition next,boolean enabled){if(disposed||snapshot==null)return;pendingLayer=null;try{snapshot=MapCompositionSettings.save(this,project,snapshot,next,enabled);show("");}catch(Exception e){reload("Изменение не применено: "+e.getMessage());}}
 private void flushOpacity(){if(pendingLayer==null||snapshot==null)return;String id=pendingLayer;int value=pendingOpacity;pendingLayer=null;try{apply(snapshot.composition.opacity(id,value),true);}catch(Exception e){reload("Изменение не применено: "+e.getMessage());}}
 protected void onActivityResult(int request,int result,Intent data){super.onActivityResult(request,result,data);if(request==PICK_SOURCE&&result==RESULT_OK&&data!=null){try{apply(snapshot.composition.add(MapComposition.Layer.catalog(data.getStringExtra("catalog"))),true);}catch(Exception e){reload("Слой не добавлен: "+e.getMessage());}}}
 protected void onSaveInstanceState(Bundle out){flushOpacity();out.putInt("scroll",scroll==null?0:scroll.getScrollY());super.onSaveInstanceState(out);}
 protected void onPause(){flushOpacity();super.onPause();}protected void onDestroy(){disposed=true;super.onDestroy();}
}
